<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>长川银行 - 值得信赖的全国性商业银行</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: "Microsoft YaHei", "PingFang SC", "Helvetica Neue", Arial, sans-serif; color: #2d3748; background: #f8fafc; line-height: 1.7; }
        a { text-decoration: none; color: inherit; }
        ul { list-style: none; }
        img { max-width: 100%; }

        /* Header */
        .top-bar { background: #0f2440; color: #a0b8d4; font-size: 13px; padding: 6px 0; }
        .top-bar .container { display: flex; justify-content: space-between; align-items: center; }
        .top-bar a { color: #a0b8d4; margin-left: 16px; transition: color .2s; }
        .top-bar a:hover { color: #fff; }

        header { background: #1a3a5c; position: sticky; top: 0; z-index: 1000; box-shadow: 0 2px 12px rgba(0,0,0,.15); }
        header .container { display: flex; align-items: center; justify-content: space-between; padding: 16px 0; }
        .logo { display: flex; align-items: center; gap: 10px; }
        .logo-icon { width: 42px; height: 42px; background: linear-gradient(135deg, #e8a020, #f5c84e); border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 900; font-size: 22px; }
        .logo-text { color: #fff; font-size: 22px; font-weight: 700; letter-spacing: 2px; }
        .logo-sub { color: #8ab4d4; font-size: 11px; display: block; letter-spacing: 1px; }

        nav { display: flex; gap: 8px; }
        nav a { color: #c8dce8; padding: 10px 18px; border-radius: 6px; font-size: 15px; transition: all .2s; }
        nav a:hover, nav a.active { background: rgba(255,255,255,.12); color: #fff; }
        .header-cta { background: #e8a020; color: #fff; padding: 10px 22px; border-radius: 6px; font-size: 14px; font-weight: 600; transition: background .2s; }
        .header-cta:hover { background: #d4911a; }

        .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

        /* Hero */
        .hero { background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 50%, #1a3a5c 100%); color: #fff; padding: 90px 0 100px; position: relative; overflow: hidden; }
        .hero::before { content: ""; position: absolute; top: -50%; right: -20%; width: 600px; height: 600px; background: radial-gradient(circle, rgba(232,160,32,.15) 0%, transparent 70%); border-radius: 50%; }
        .hero::after { content: ""; position: absolute; bottom: -30%; left: -10%; width: 400px; height: 400px; background: radial-gradient(circle, rgba(255,255,255,.05) 0%, transparent 70%); border-radius: 50%; }
        .hero .container { position: relative; z-index: 1; display: flex; align-items: center; gap: 60px; }
        .hero-content { flex: 1; }
        .hero h1 { font-size: 42px; font-weight: 700; line-height: 1.3; margin-bottom: 20px; }
        .hero h1 span { color: #f5c84e; }
        .hero p { font-size: 17px; color: #b8d4e8; margin-bottom: 32px; max-width: 520px; }
        .hero-btns { display: flex; gap: 14px; flex-wrap: wrap; }
        .btn { display: inline-block; padding: 13px 30px; border-radius: 6px; font-size: 15px; font-weight: 600; cursor: pointer; border: none; transition: all .2s; }
        .btn-primary { background: #e8a020; color: #fff; }
        .btn-primary:hover { background: #d4911a; transform: translateY(-1px); }
        .btn-outline { background: transparent; color: #fff; border: 2px solid rgba(255,255,255,.4); }
        .btn-outline:hover { border-color: #fff; background: rgba(255,255,255,.08); }

        .hero-stats { display: flex; gap: 40px; margin-top: 48px; padding-top: 32px; border-top: 1px solid rgba(255,255,255,.15); }
        .hero-stat { text-align: center; }
        .hero-stat .num { font-size: 32px; font-weight: 700; color: #f5c84e; }
        .hero-stat .label { font-size: 13px; color: #8ab4d4; margin-top: 4px; }

        /* Sections */
        .section { padding: 72px 0; }
        .section-title { text-align: center; margin-bottom: 48px; }
        .section-title h2 { font-size: 32px; font-weight: 700; color: #1a3a5c; margin-bottom: 12px; }
        .section-title p { font-size: 16px; color: #64748b; max-width: 560px; margin: 0 auto; }
        .section-title .line { width: 50px; height: 4px; background: #e8a020; margin: 16px auto 0; border-radius: 2px; }

        /* Service Cards */
        .services-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
        .service-card { background: #fff; border-radius: 12px; padding: 32px 28px; box-shadow: 0 2px 12px rgba(0,0,0,.04); transition: all .3s; border: 1px solid #e8edf2; }
        .service-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(26,58,92,.1); border-color: #c8dce8; }
        .service-icon { width: 52px; height: 52px; background: linear-gradient(135deg, #eef4fa, #dce8f2); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 24px; margin-bottom: 20px; }
        .service-card h3 { font-size: 18px; font-weight: 700; color: #1a3a5c; margin-bottom: 10px; }
        .service-card p { font-size: 14px; color: #64748b; line-height: 1.8; }
        .service-card .link { display: inline-block; margin-top: 16px; color: #2c6fad; font-size: 14px; font-weight: 600; }
        .service-card .link:hover { color: #1a3a5c; }

        /* Popular Products */
        .products-section { background: #fff; }
        .products-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
        .product-card { border: 1px solid #e2e8f0; border-radius: 10px; padding: 24px; text-align: center; transition: all .2s; }
        .product-card:hover { border-color: #e8a020; box-shadow: 0 4px 16px rgba(232,160,32,.12); }
        .product-card .rate { font-size: 28px; font-weight: 700; color: #e8a020; margin: 12px 0 4px; }
        .product-card .rate small { font-size: 14px; color: #64748b; font-weight: 400; }
        .product-card h4 { font-size: 15px; color: #1a3a5c; font-weight: 600; }
        .product-card .desc { font-size: 12px; color: #94a3b8; margin-top: 6px; }

        /* News */
        .news-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
        .news-card { background: #fff; border-radius: 10px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,.04); }
        .news-img { height: 180px; background: linear-gradient(135deg, #dce8f2, #eef4fa); display: flex; align-items: center; justify-content: center; font-size: 40px; }
        .news-body { padding: 20px 24px; }
        .news-body .date { font-size: 12px; color: #94a3b8; margin-bottom: 8px; }
        .news-body h4 { font-size: 15px; color: #1a3a5c; font-weight: 600; line-height: 1.5; }

        /* CTA Banner */
        .cta-banner { background: linear-gradient(135deg, #1a3a5c, #2c5f8a); padding: 60px 0; text-align: center; color: #fff; }
        .cta-banner h2 { font-size: 28px; margin-bottom: 12px; }
        .cta-banner p { color: #b8d4e8; margin-bottom: 28px; font-size: 16px; }

        /* Footer */
        footer { background: #0f2440; color: #8ab4d4; padding: 56px 0 0; }
        .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; padding-bottom: 40px; border-bottom: 1px solid rgba(255,255,255,.08); }
        .footer-grid h4 { color: #fff; font-size: 15px; margin-bottom: 16px; }
        .footer-grid a { display: block; font-size: 13px; color: #8ab4d4; margin-bottom: 10px; transition: color .2s; }
        .footer-grid a:hover { color: #f5c84e; }
        .footer-about p { font-size: 13px; line-height: 1.8; margin-top: 12px; }
        .footer-bottom { text-align: center; padding: 20px 0; font-size: 12px; color: #5a7a96; }

        /* Responsive */
        @media (max-width: 1024px) {
            .services-grid { grid-template-columns: repeat(2, 1fr); }
            .products-grid { grid-template-columns: repeat(2, 1fr); }
            .footer-grid { grid-template-columns: repeat(2, 1fr); }
        }
        @media (max-width: 768px) {
            .hero .container { flex-direction: column; text-align: center; }
            .hero h1 { font-size: 30px; }
            .hero-btns { justify-content: center; }
            .hero-stats { justify-content: center; flex-wrap: wrap; gap: 24px; }
            nav { display: none; }
            .services-grid { grid-template-columns: 1fr; }
            .products-grid { grid-template-columns: 1fr 1fr; }
            .news-grid { grid-template-columns: 1fr; }
            .footer-grid { grid-template-columns: 1fr; }
        }
    </style>
</head>
<body>
